<?php
declare(strict_types=1);$config=require __DIR__.'/../config/config.php';require_once __DIR__.'/../app/Database.php';require_once __DIR__.'/../app/Auth.php';try{$u=(new Auth($config))->requireUser();if((int)$u['id']<1)json_response(['ok'=>true,'items'=>[],'temporary'=>true]);$pdo=Database::connection($config);$in=request_json();$op=(string)($in['op']??'list');if($op==='list'){$s=$pdo->prepare('SELECT id,title,provider,model,created_at,updated_at FROM conversations WHERE user_id=? ORDER BY updated_at DESC');$s->execute([(int)$u['id']]);json_response(['ok'=>true,'items'=>$s->fetchAll()]);}if($op==='create'){$s=$pdo->prepare('INSERT INTO conversations(user_id,title,provider) VALUES(?,?,?)');$s->execute([(int)$u['id'],trim((string)($in['title']??'Nova conversa')),(string)($in['provider']??'lmstudio')]);json_response(['ok'=>true,'id'=>$pdo->lastInsertId()]);}$id=(int)($in['id']??0);$s=$pdo->prepare('SELECT id FROM conversations WHERE id=? AND user_id=?');$s->execute([$id,(int)$u['id']]);if(!$s->fetch())throw new RuntimeException('Conversa não encontrada.');if($op==='rename'){$s=$pdo->prepare('UPDATE conversations SET title=? WHERE id=? AND user_id=?');$s->execute([trim((string)($in['title']??'')),$id,(int)$u['id']]);json_response(['ok'=>true]);}if($op==='delete'){$s=$pdo->prepare('DELETE FROM conversations WHERE id=? AND user_id=?');$s->execute([$id,(int)$u['id']]);json_response(['ok'=>true]);}if($op==='messages'){$s=$pdo->prepare('SELECT role,content,tool_call_id,created_at FROM messages WHERE conversation_id=? ORDER BY id');$s->execute([$id]);json_response(['ok'=>true,'items'=>$s->fetchAll()]);}if($op==='export'){$s=$pdo->prepare('SELECT role,content,created_at FROM messages WHERE conversation_id=? ORDER BY id');$s->execute([$id]);$rows=$s->fetchAll();$out="# Conversa\n\n";foreach($rows as $r)$out.='## '.ucfirst($r['role'])." — {$r['created_at']}\n\n{$r['content']}\n\n";json_response(['ok'=>true,'markdown'=>$out]);}throw new InvalidArgumentException('Operação inválida.');}catch(Throwable $e){json_response(['ok'=>false,'error'=>$e->getMessage()],400);}
?>
